import sys

def main():
    s = sys.stdin.read().strip()
    n = len(s)
    suffixes = set()

    for i in range(5, n):
        for l in [2, 3]:
            if i + l <= n:
                suffix = s[i:i+l]
                if i - l >= 5 and s[i-l:i] != suffix:
                    suffixes.add(suffix)

    suffixes = sorted(suffixes)
    print(len(suffixes))
    for suffix in suffixes:
        print(suffix)

main()
